class Solution {
    public int[] distanceToCycle(int n, int[][] edges) {
        List<Integer>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        int[] deg = new int[n];
        for (int[] e : edges) {
            g[e[0]].add(e[1]);
            g[e[1]].add(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }
        boolean[] removed = new boolean[n];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (deg[i] == 1) q.add(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            removed[u] = true;
            for (int v : g[u]) if (--deg[v] == 1) q.add(v);
        }
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) if (!removed[i]) { ans[i] = 0; q.add(i); }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) if (ans[v] == -1) { ans[v] = ans[u] + 1; q.add(v); }
        }
        return ans;
    }
}
